-- Metadata only: no workbook bytes or raw source cells are stored.
alter table task_import_batches
  add column if not exists outcome text not null default 'completed' check (outcome in ('validated','completed','replayed','failed')),
  add column if not exists safe_file_label text check (safe_file_label is null or safe_file_label ~ '^[A-Za-z0-9._ -]{1,120}$'),
  add column if not exists valid_count integer not null default 0 check (valid_count between 0 and 500),
  add column if not exists error_count integer not null default 0 check (error_count between 0 and 500),
  add column if not exists one_time_count integer not null default 0 check (one_time_count between 0 and 500),
  add column if not exists recurring_count integer not null default 0 check (recurring_count between 0 and 500),
  add column if not exists initial_instance_count integer not null default 0 check (initial_instance_count between 0 and 500),
  add column if not exists validated_at timestamptz,
  add column if not exists completed_at timestamptz;
create index if not exists idx_task_import_batches_creator_created on task_import_batches(tenant_id, created_by, created_at desc);

drop policy if exists task_import_batches_select on task_import_batches;
create policy task_import_batches_select on task_import_batches for select to authenticated using (
  current_profile_is_active() and tenant_id = current_tenant_id() and
  (current_role_level() in ('super_admin','admin') or created_by = (current_profile()).id)
);

create or replace function task_bulk_import_validation(p_payload jsonb, p_hash text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_actor user_profiles; v_row jsonb; v_index integer := 0; v_issues jsonb := '[]'; v_branch uuid; v_department uuid; v_category uuid; v_doer uuid; v_watcher text; v_form uuid; v_count integer; v_recurring integer := 0; v_once integer := 0;
begin
  select * into v_actor from current_profile();
  if v_actor.id is null or not current_profile_is_active() or v_actor.user_role not in ('super_admin','admin','manager') then raise exception 'Task bulk import denied' using errcode='42501'; end if;
  if jsonb_typeof(p_payload) <> 'object' or p_payload - 'tasks' <> '{}'::jsonb or jsonb_typeof(p_payload->'tasks') <> 'array' or jsonb_array_length(p_payload->'tasks') not between 1 and 500 then raise exception 'Bulk import must contain 1 to 500 tasks' using errcode='22023'; end if;
  if coalesce(p_hash,'') !~ '^[a-f0-9]{64}$' then raise exception 'Bulk import hash is invalid' using errcode='22023'; end if;
  for v_row in select value from jsonb_array_elements(p_payload->'tasks') loop
    v_index := v_index + 1;
    if jsonb_typeof(v_row) <> 'object' then v_issues := v_issues || jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','row','reason','Task must be an object','guidance','Use the downloaded format.','severity','error')); continue; end if;
    if nullif(btrim(v_row->>'title'),'') is null or length(btrim(v_row->>'title')) > 200 then v_issues := v_issues || jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','title','reason','Title is required and limited to 200 characters','guidance','Correct the title.','severity','error')); end if;
    if v_row->>'task_mode' not in ('one_time','recurring') then v_issues := v_issues || jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','task_mode','reason','Unsupported task mode','guidance','Use one_time or recurring.','severity','error')); continue; end if;
    if v_actor.user_role='manager' and nullif(v_row->>'branch','') is not null and not exists(select 1 from branches where tenant_id=v_actor.tenant_id and id=v_actor.branch_id and (lower(name)=lower(btrim(v_row->>'branch')) or lower(code)=lower(btrim(v_row->>'branch')))) then v_issues := v_issues || jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','branch','reason','Manager branch scope denied','guidance','Use your authorized branch.','severity','error')); end if;
    select id into v_branch from branches where tenant_id=v_actor.tenant_id and is_active and (nullif(v_row->>'branch','') is null or lower(name)=lower(btrim(v_row->>'branch')) or lower(code)=lower(btrim(v_row->>'branch'))) order by id limit 1; v_branch := coalesce(v_branch,v_actor.branch_id);
    select id into v_department from departments where tenant_id=v_actor.tenant_id and is_active and (branch_id=v_branch or branch_id is null) and (nullif(v_row->>'department','') is null or lower(name)=lower(btrim(v_row->>'department')) or lower(code)=lower(btrim(v_row->>'department'))) order by id limit 1;
    select id into v_category from dropdown_masters where tenant_id=v_actor.tenant_id and master_type='task_category' and is_active and (nullif(v_row->>'category','') is null or lower(label)=lower(btrim(v_row->>'category')) or lower(value)=lower(btrim(v_row->>'category'))) order by sort_order limit 1;
    if v_branch is null or v_category is null then v_issues := v_issues || jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field',case when v_branch is null then 'branch' else 'category' end,'reason','Reference is invalid or unavailable','guidance','Use Reference Data values.','severity','error')); end if;
    if nullif(v_row->>'published_form','') is not null then select id into v_form from form_templates where tenant_id=v_actor.tenant_id and is_active and lower(name)=lower(btrim(v_row->>'published_form')) order by id limit 1; if v_form is null then v_issues:=v_issues||jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','published_form','reason','Published form is unavailable','guidance','Use an authorized published form.','severity','error')); end if; end if;
    if v_row->>'task_mode'='one_time' then v_once:=v_once+1; if jsonb_typeof(v_row->'doer_emails') <> 'array' or jsonb_array_length(v_row->'doer_emails')=0 then v_issues:=v_issues||jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','doer_emails','reason','At least one doer is required','guidance','Use active employee emails.','severity','error')); end if; for v_watcher in select jsonb_array_elements_text(coalesce(v_row->'doer_emails','[]')) union all select jsonb_array_elements_text(coalesce(v_row->'watcher_emails','[]')) loop select id into v_doer from user_profiles where tenant_id=v_actor.tenant_id and working_status='active' and is_login_enabled and lower(email)=lower(btrim(v_watcher)) and (v_actor.user_role <> 'manager' or branch_id=v_actor.branch_id); if v_doer is null then v_issues:=v_issues||jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','participants','reason','Participant is unavailable or outside scope','guidance','Use authorized active employee emails.','severity','error')); end if; end loop; else v_recurring:=v_recurring+1; select id into v_doer from user_profiles where tenant_id=v_actor.tenant_id and working_status='active' and is_login_enabled and lower(email)=lower(btrim(v_row->>'primary_doer_email')) and (v_actor.user_role <> 'manager' or branch_id=v_actor.branch_id); if v_doer is null or coalesce(jsonb_array_length(v_row->'doer_emails'),0)>0 or coalesce(jsonb_array_length(v_row->'watcher_emails'),0)>0 or v_row->>'recurrence_kind' not in ('daily','weekly','monthly_day','monthly_nth') then v_issues:=v_issues||jsonb_build_array(jsonb_build_object('sheet','Tasks','row',v_index+1,'field','recurrence','reason','Recurring participant or schedule is invalid','guidance','Use one primary doer and supported recurrence fields.','severity','error')); end if; end if;
  end loop;
  select jsonb_array_length(v_issues) into v_count;
  return jsonb_build_object('valid',v_count=0,'canonical_hash',p_hash,'summary',jsonb_build_object('requested_count',v_index,'valid_count',case when v_count=0 then v_index else 0 end,'error_count',v_count,'one_time_count',v_once,'recurring_count',v_recurring,'initial_instance_count',v_recurring),'issues',v_issues);
end $$;

create or replace function validate_task_bulk_import(p_payload jsonb, p_import_hash text) returns jsonb language plpgsql security definer set search_path=public as $$ begin return task_bulk_import_validation(p_payload,p_import_hash); end $$;
create or replace function import_task_bulk_with_audit(p_payload jsonb, p_import_hash text, p_file_label text) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_actor user_profiles; v_check jsonb; v_row jsonb; v_batch task_import_batches; v_doers uuid[]; v_watchers uuid[]; v_primary uuid; v_payload jsonb; v_rrule text; v_template uuid; v_once integer:=0; v_rec integer:=0;
begin
 select * into v_actor from current_profile(); v_check:=task_bulk_import_validation(p_payload,p_import_hash); if not coalesce((v_check->>'valid')::boolean,false) then raise exception 'Bulk import validation failed' using errcode='22023'; end if;
 if coalesce(p_file_label,'') !~ '^[A-Za-z0-9._ -]{1,120}$' then raise exception 'File label is unsafe' using errcode='22023'; end if;
 select * into v_batch from task_import_batches where tenant_id=v_actor.tenant_id and import_hash=p_import_hash for update; if v_batch.id is not null then return jsonb_build_object('batch_id',v_batch.id,'replayed',true,'outcome',v_batch.outcome,'created_count',v_batch.created_count); end if;
 insert into task_import_batches(tenant_id,created_by,import_hash,source_headers,requested_count,valid_count,error_count,one_time_count,recurring_count,initial_instance_count,safe_file_label,outcome,validated_at,completed_at) values(v_actor.tenant_id,v_actor.id,p_import_hash,array['task_bulk_import'],jsonb_array_length(p_payload->'tasks'),jsonb_array_length(p_payload->'tasks'),0,(v_check->'summary'->>'one_time_count')::int,(v_check->'summary'->>'recurring_count')::int,(v_check->'summary'->>'initial_instance_count')::int,p_file_label,'completed',now(),now()) returning * into v_batch;
 for v_row in select value from jsonb_array_elements(p_payload->'tasks') loop
  select array_agg(id order by id) into v_doers from user_profiles where tenant_id=v_actor.tenant_id and lower(email)=any(array(select lower(jsonb_array_elements_text(coalesce(v_row->'doer_emails','[]')))));
  select array_agg(id order by id) into v_watchers from user_profiles where tenant_id=v_actor.tenant_id and lower(email)=any(array(select lower(jsonb_array_elements_text(coalesce(v_row->'watcher_emails','[]')))));
  if v_row->>'task_mode'='one_time' then v_payload:=jsonb_build_object('title',v_row->>'title','description',nullif(v_row->>'description',''),'planned_datetime',v_row->>'planned_at','priority',coalesce(nullif(v_row->>'priority',''),'medium'),'branch_id',(select id from branches where tenant_id=v_actor.tenant_id and (lower(name)=lower(v_row->>'branch') or lower(code)=lower(v_row->>'branch')) limit 1),'department_id',null,'category_id',(select id from dropdown_masters where tenant_id=v_actor.tenant_id and master_type='task_category' and (lower(label)=lower(v_row->>'category') or lower(value)=lower(v_row->>'category')) limit 1),'requires_upload',coalesce((v_row->>'requires_upload')::boolean,false),'requires_remark',coalesce((v_row->>'requires_remark')::boolean,false),'requires_form',nullif(v_row->>'published_form','') is not null,'form_template_id',(select id from form_templates where tenant_id=v_actor.tenant_id and lower(name)=lower(v_row->>'published_form') limit 1)); perform create_delegation_task_with_audit(v_payload,v_doers,coalesce(v_watchers,'{}'),coalesce(v_row->'checklist','[]')); v_once:=v_once+1; else select id into v_primary from user_profiles where tenant_id=v_actor.tenant_id and lower(email)=lower(v_row->>'primary_doer_email'); v_rrule:='RRULE:FREQ='||case v_row->>'recurrence_kind' when 'daily' then 'DAILY' when 'weekly' then 'WEEKLY' else 'MONTHLY' end||';INTERVAL='||coalesce(v_row->>'recurrence_interval','1'); if v_row->>'recurrence_kind'='weekly' then v_rrule:=v_rrule||';BYDAY='||replace(replace(replace(replace(replace(replace(replace(array_to_string(array(select jsonb_array_elements_text(v_row->'weekly_days')),','),'MON','MO'),'TUE','TU'),'WED','WE'),'THU','TH'),'FRI','FR'),'SAT','SA'),'SUN','SU'); end if; if v_row->>'recurrence_kind'='monthly_day' then v_rrule:=v_rrule||';BYMONTHDAY='||v_row->>'monthly_day'; end if; if v_row->>'recurrence_kind'='monthly_nth' then v_rrule:=v_rrule||';BYDAY='||v_row->>'monthly_nth'||replace(replace(replace(replace(replace(replace(replace(v_row->>'monthly_weekday','MON','MO'),'TUE','TU'),'WED','WE'),'THU','TH'),'FRI','FR'),'SAT','SA'),'SUN','SU'); end if; v_template:=save_task_template_with_audit(null,jsonb_build_object('title',v_row->>'title','description',nullif(v_row->>'description',''),'recurrence_rule',v_rrule,'planned_time',substring(v_row->>'planned_at' from 12 for 5),'priority',coalesce(nullif(v_row->>'priority',''),'medium'),'requires_upload',coalesce((v_row->>'requires_upload')::boolean,false),'requires_remark',coalesce((v_row->>'requires_remark')::boolean,false),'requires_form',false,'form_template_id',null,'default_assignee_type','specific_user','default_assignee_user_id',v_primary,'default_assignee_role',null,'branch_id',v_actor.branch_id,'department_id',null,'category_id',(select id from dropdown_masters where tenant_id=v_actor.tenant_id and master_type='task_category' order by sort_order limit 1),'checklist_items',coalesce(v_row->'checklist','[]'),'is_active',true,'initial_planned_datetime',v_row->>'planned_at')); v_rec:=v_rec+1; end if;
 end loop;
 update task_import_batches set created_count=v_once+v_rec where id=v_batch.id; insert into audit_logs(tenant_id,actor_user_id,action,module,record_id,new_value) values(v_actor.tenant_id,v_actor.id,'task_bulk_imported','task_import_batches',v_batch.id,jsonb_build_object('one_time_count',v_once,'recurring_count',v_rec,'import_hash',p_import_hash)); return jsonb_build_object('batch_id',v_batch.id,'created_count',v_once+v_rec,'replayed',false,'outcome','completed');
end $$;
revoke all on function task_bulk_import_validation(jsonb,text), validate_task_bulk_import(jsonb,text), import_task_bulk_with_audit(jsonb,text,text) from public, anon, service_role;
grant execute on function validate_task_bulk_import(jsonb,text), import_task_bulk_with_audit(jsonb,text,text) to authenticated;
notify pgrst, 'reload schema';
